    "starterCode": "# Your code here\n",
    "solution": "import csv\n\ndef get_rows():\n    file = open(\"passwords.csv\", \"r\")\n    rows = []\n    for row in csv.reader(file):\n        rows.append(row)\n    file.close()\n    return rows\n\ndef score(password):\n    points = 0\n    if len(password) >= 8:\n        points = points + 1\n    if password.lower() != password:\n        points = points + 1\n    if password.upper() != password:\n        points = points + 1\n    if any(ch.isdigit() for ch in password):\n        points = points + 1\n    if any(ch in \"!£$%&<*@\" for ch in password):\n        points = points + 1\n    return points\n\ndef get_password():\n    while True:\n        password = input(\"Enter a password: \")\n        points = score(password)\n        if points <= 2:\n            print(\"That is a weak password, try again\")\n        elif points <= 4:\n            print(\"This password could be improved.\")\n            again = input(\"Do you want to try again? (y/n) \")\n            if again != \"y\":\n                return password\n        else:\n            print(\"You have selected a strong password\")\n            return password\n\ndef save(rows):\n    file = open(\"passwords.csv\", \"w\")\n    for row in rows:\n        file.write(row[0] + \",\" + row[1] + \"\\n\")\n    file.close()\n\nchoice = \"\"\nwhile choice != \"4\":\n    print(\"1) Create a new User ID\")\n    print(\"2) Change a password\")\n    print(\"3) Display all User IDs\")\n    print(\"4) Quit\")\n    choice = input(\"Enter Selection: \")\n    rows = get_rows()\n    ids = [row[0] for row in rows]\n    if choice == \"1\":\n        user = input(\"Enter a new user ID: \")\n        while user in ids:\n            print(\"That user ID is already taken\")\n            user = input(\"Enter another user ID: \")\n        rows.append([user, get_password()])\n        save(rows)\n    elif choice == \"2\":\n        user = input(\"Enter your user ID: \")\n        if user in ids:\n            rows[ids.index(user)][1] = get_password()\n            save(rows)\n        else:\n            print(\"That user ID does not exist\")\n    elif choice == \"3\":\n        for user in ids:\n            print(user)\n    elif choice != \"4\":\n        print(\"Incorrect selection\")",
